  "output": "import { Inject, InternalServerErrorException, Logger, forwardRef } from '@nestjs/common';
import flattenDeep from 'lodash.flattendeep';
import { InfluxService } from '../../influx/influx.service.js';
import { fromTemporaryCredentials } from '@aws-sdk/credential-providers';
import { getAllInstanceIDs, getAllRegions } from '../../utils/aws/awsEc2.js';
import { InstanceUptimeEntity } from './entities/instanceUptime.entity.js';
import { OnQueueFailed, Process, Processor } from '@nestjs/bull';
import { infrastructureType } from '../../dimensions/dto/create-dimension.dto.js';
import { SchedulerEntity } from '../../scheduler/entities/scheduler.entity.js';
import { Job } from 'bull';
import { AuditService } from '../../audit/audit.service.js';
import { AuditScope } from '../../audit/entities/audit.interface.js';
import { logger } from '@azure/identity';

@Processor('scheduler_queue')
export class InstanceUptimeService {
    private static readonly logger = new Logger(InstanceUptimeService.name);
    constructor(@Inject(forwardRef(() => InfluxService)) readonly InfluxService: InfluxService) {}
    @Process(infrastructureType.podCPUHours)
    async getInstanceUptime({ data: { scheduleParameters, businessID, subject, rate } }: Job<SchedulerEntity>) {
        if ('iamRoleArn' in scheduleParameters) {
            const { iamRoleArn, externalId } = scheduleParameters;
            InstanceUptimeService.logger.log('Processing Automated Instance Uptime gathering event, logging inputs', {
                rate,
                businessID,
                externalId,
                subject,
            });
            const creds = fromTemporaryCredentials({
                params: { RoleArn: iamRoleArn, ExternalId: externalId ? externalId : undefined },
                clientConfig: { region: 'us-east-1' },
            });
            const regions = await getAllRegions(creds);
            const instances = await Promise.all(
                regions.map(async (region) => {
                    try {
                        const instance = await getAllInstanceIDs(region, creds);
                        return instance;
                    } catch (e) {
                        InstanceUptimeService.logger.error("Couldn't get instance IDs", e);
                        return undefined;
                    }
                }),
            );

            // Put instances in influx with the following schema
            const flattenedListOfInstances = flattenDeep(instances);
            const filteredInstances = flattenedListOfInstances.filter((element) => element);
            const points = await Promise.all(
                filteredInstances.map(
                    ({
                        InstanceId: instanceID,
                        State: status,
                        Tags: metadata,
                        LaunchTime: startTime,
                        Memory,
                        CpuCores,
                        PrivateDnsName,
                        InstanceType,
                        region,
                    }) =>
                        InstanceUptimeEntity.transformer(
                            new InstanceUptimeEntity({
                                instanceID,
                                status,
                                metadata,
                                startTime,
                                businessID,
                                memory: Memory,
                                cpuCores: CpuCores,
                                privateDNS: PrivateDnsName,
                                instanceType: InstanceType,
                                region,
                            }),
                            this.InfluxService,
                        ),
                ),
            );
            InstanceUptimeService.logger.log('Loading Instance Uptime Entity Points into Influx', points.length);
            const vaildPoints = points.filter((element) => element);
            const { loadPoints } = this.InfluxService;
            // InstanceMetaData | status (tag)  | instanceID (string field) | price (tag)|  ... all other tags
            const results = await loadPoints(`${process.env.STAGE}-usage-data`, process.env.INFLUX_ORG, vaildPoints);
            return results;
        } else {
            throw new InternalServerErrorException('iamRoleArn not found in scheduleParameters');
        }
    }
    @OnQueueFailed({ name: infrastructureType.podCPUHours })
    jobFailure(job: Job) {
        AuditService.publishEvent({
            message: 'Failed to gather instance uptime',
            data: job.data,
            topic: AuditScope.ERROR,
        });
    }
}
import { IsArray, IsNotEmpty, IsOptional, IsString } from 'class-validator';

import { infrastructureType } from '../../../dimensions/dto/create-dimension.dto.js';
import {
    IAMAccessCredentials,
    InfrastructureAccessInformation,
} from '../../../measurement-config/entities/measurement-config.entity.js';

export class NodeUptimeDto extends IAMAccessCredentials {
    /** 
     * The list of tags which a service is filterable by.
     * Each tag key must begin with "tag_" in order to be usuable by Metering
     * 
     * @example
     * 
      [
    { filterKey: 'tag_myCoolTag123__somethingElse', filterValue: 'somethingReallyImportant1234' },
    { filterKey: 'anotherKey', filterValue: 'anotherValue' },
      ]
     *
     **/
    @IsArray()
    @IsOptional()
    public filters?: Array<any>;
    /**
     *
     * Static string indicating the dimensionType
     */
    @IsString()
    @IsNotEmpty()
    public dimensionType: infrastructureType.podCPUHours;

    @IsOptional()
    public dimensionId?: string;
}
import { Point } from '@influxdata/influxdb-client';
import { Logger } from '@nestjs/common';
import { InfluxService } from '../../../influx/influx.service.js';

export class InstanceUptimeEntity {
    private static readonly logger = new Logger(InstanceUptimeEntity.name);

    public static _measurement = 'InstanceMetaData';
    public instanceID: string;
    public status: string;
    public metadata: any;
    public startTime: string;
    public businessID: string;
    public ram: string;
    public cpu: string;
    public privateDNS: string;
    public instanceType: string;
    public region: string;

    constructor({
        instanceID,
        status: { Name },
        metadata,
        startTime,
        businessID,
        memory,
        cpuCores,
        privateDNS,
        instanceType,
        region,
    }) {
        this.instanceID = instanceID;
        this.status = Name;
        this.metadata = metadata;
        this.startTime = startTime;
        this.businessID = businessID;
        this.ram = memory;
        this.cpu = cpuCores;
        this.privateDNS = privateDNS;
        this.instanceType = instanceType;
        this.region = region;
    }
    public static async transformer(
        instanceUptimeEntity: InstanceUptimeEntity,
        influxService: InfluxService,
    ): Promise<Point | false> {
        const { instanceID, status, metadata, startTime, businessID } = instanceUptimeEntity;

        const uptimeEntityPoint = influxService.getPoint(InstanceUptimeEntity._measurement);
        const startTimeDate = new Date(startTime);
        uptimeEntityPoint.tag('instanceID', instanceID);
        uptimeEntityPoint.tag('instanceType', instanceUptimeEntity.instanceType);
        uptimeEntityPoint.tag('cpuCores', instanceUptimeEntity.cpu);
        uptimeEntityPoint.tag('memory', instanceUptimeEntity.ram);
        uptimeEntityPoint.tag('privateDNS', instanceUptimeEntity.privateDNS);

        uptimeEntityPoint.stringField('status', status);
        uptimeEntityPoint.tag('businessID', businessID);
        uptimeEntityPoint.tag('startTime', startTimeDate.getTime().toString());
        uptimeEntityPoint.tag('region', instanceUptimeEntity.region);
        if (metadata) {
            metadata.forEach(({ Key, Value }) => {
                uptimeEntityPoint.tag(`meteringmetadata_${Key}`, Value.toString());
            });
        }

        return uptimeEntityPoint;
    }
    public static dbModelToEntity(dbModel: any): InstanceUptimeEntity {
        const {
            instanceID,
            _value,
            startTime,
            businessID,
            memory,
            cpuCores,
            privateDNS,
            instanceType,
            region,
            ...rest
        } = dbModel;
        const metadata = Object.keys(rest)
            .filter((key) => /meteringmetadata_/.test(key))
            .reduce((acc, key) => {
                acc[key] = rest[key];
                return acc;
            }, {});
        console.log('instanceUptime Region', region);
        return new InstanceUptimeEntity({
            instanceID,
            status: { Name: _value },
            metadata,
            startTime,
            businessID,
            memory,
            cpuCores,
            privateDNS,
            instanceType,
            region,
        });
    }
}
