import { Logger } from '@nestjs/common';
import { getDocument, getDocumentsUnderPrefix } from '../../utils/aws/s3.js';

/**
 * An AWS account a business has handed us for measurement.
 */
export class MeteredAccount {
    /**
     * The account the metering role lives in.
     * @example "445566778899"
     */
    public accountId: string;
    /**
     * The role we assume to read the account.
     * @example "arn:aws:iam::445566778899:role/metering-metering"
     */
    public roleArn: string;
    /**
     * The external id the role's trust policy asks for, when it asks for one.
     */
    public externalId?: string;
    /**
     * The region the business runs the metered workload in.
     * @example "us-east-1"
     */
    public region: string;
}

/**
 * One line of a customer's onboarding record: an account the customer has been
 * onboarded onto, and whether the account is theirs alone.
 */
export class OnboardedAccount {
    /**
     * The account the customer is onboarded for.
     * @example "445566778899"
     */
    public accountId: string;
    /**
     * True when the account only ever runs this customer's workload. Everything
     * metered in a dedicated account belongs to its customer, whatever the
     * resource tags happen to say.
     */
    public dedicated?: boolean;
}

/**
 * The per customer onboarding record a business keeps in its metering bucket,
 * one object per customer under {@link MeteringRegistry.customerRecordPrefix}.
 * Only customers with such a record are billable.
 */
export class CustomerOnboardingRecord {
    /**
     * The id the business tags its resources with.
     * @example "cus_harbor"
     */
    public customerId: string;
    /**
     * Human readable name, only used for logging.
     */
    public displayName?: string;
    /**
     * The accounts the customer has been onboarded for.
     */
    public accounts: Array<OnboardedAccount>;

    static async loadAll(bucket: string, prefix: string): Promise<Array<CustomerOnboardingRecord>> {
        return getDocumentsUnderPrefix<CustomerOnboardingRecord>(bucket, prefix);
    }
}

/**
 * Splits a `meteringCustomerId` tag value into the customer ids it names. The
 * tag carries a comma separated list so a shared machine can name every tenant
 * running on it.
 */
export const parseTaggedCustomerIds = (tagValue?: string): Array<string> =>
    (tagValue ?? '')
        .split(',')
        .map((customerId) => customerId.trim())
        .filter((customerId) => customerId.length > 0);

/**
 * The onboarding records of a business, indexed by account, used to decide who
 * owns a metered resource.
 */
export class OnboardedCustomers {
    private static readonly logger = new Logger(OnboardedCustomers.name);

    /** accountId -> customer ids genuinely onboarded for the account */
    private readonly tenantsByAccount = new Map<string, Set<string>>();
    /** accountId -> customer ids claiming the account as dedicated */
    private readonly dedicatedClaimsByAccount = new Map<string, Set<string>>();
    /** every billable customer id */
    public readonly customerIds: Set<string> = new Set<string>();

    constructor(records: Array<CustomerOnboardingRecord> = []) {
        records.forEach((record) => {
            const customerId = record?.customerId?.trim();
            if (!customerId) {
                OnboardedCustomers.logger.warn('Ignoring onboarding record without a customerId');
                return;
            }
            this.customerIds.add(customerId);
            (record.accounts ?? []).forEach((account) => {
                const accountId = account?.accountId?.toString().trim();
                if (!accountId) {
                    OnboardedCustomers.logger.warn(`Ignoring onboarded account without an accountId for ${customerId}`);
                    return;
                }
                if (!this.tenantsByAccount.has(accountId)) {
                    this.tenantsByAccount.set(accountId, new Set<string>());
                }
                this.tenantsByAccount.get(accountId).add(customerId);
                if (account.dedicated === true) {
                    if (!this.dedicatedClaimsByAccount.has(accountId)) {
                        this.dedicatedClaimsByAccount.set(accountId, new Set<string>());
                    }
                    this.dedicatedClaimsByAccount.get(accountId).add(customerId);
                }
            });
        });
    }

    static async load(bucket: string, prefix: string): Promise<OnboardedCustomers> {
        return new OnboardedCustomers(await CustomerOnboardingRecord.loadAll(bucket, prefix));
    }

    /**
     * The customers onboarded for an account, sorted for stable output.
     */
    public tenantsOf(accountId: string): Array<string> {
        return [...(this.tenantsByAccount.get(accountId) ?? new Set<string>())].sort();
    }

    /**
     * The single customer an account is dedicated to, when there is one. An
     * account two customers both claim as dedicated is not dedicated to anyone,
     * so it is treated as shared.
     */
    public dedicatedOwnerOf(accountId: string): string | undefined {
        const claims = [...(this.dedicatedClaimsByAccount.get(accountId) ?? new Set<string>())].sort();
        if (claims.length === 1) {
            return claims[0];
        }
        if (claims.length > 1) {
            OnboardedCustomers.logger.warn(
                `Account ${accountId} is claimed as dedicated by ${claims.join(', ')}, treating it as shared`,
            );
        }
        return undefined;
    }

    public isDedicated(accountId: string): boolean {
        return this.dedicatedOwnerOf(accountId) !== undefined;
    }

    /**
     * Works out which customers a metered resource belongs to.
     *
     * - In an account dedicated to a single customer everything belongs to that
     *   customer, whatever the tags name, including when they name nothing.
     * - In a shared account the resource belongs to the tagged customers that
     *   are genuinely onboarded for the account, and is shared between them.
     * - Anything else is unplaceable and returns an empty list, so it stays off
     *   the bill.
     */
    public ownersOf(accountId: string, taggedCustomerIds: Array<string> = []): Array<string> {
        const dedicatedOwner = this.dedicatedOwnerOf(accountId);
        if (dedicatedOwner) {
            return [dedicatedOwner];
        }
        const tenants = this.tenantsByAccount.get(accountId) ?? new Set<string>();
        return [...new Set(taggedCustomerIds)].filter((customerId) => tenants.has(customerId)).sort();
    }
}

/**
 * The onboarding record a business keeps in its metering bucket. It is written
 * by the onboarding flow and read by every collector that has to sweep more
 * than one account.
 */
export class MeteringRegistry {
    public businessID: string;
    /**
     * Key prefix the per customer onboarding records sit under in the same
     * bucket, one object per customer.
     * @example "onboarding/customers/"
     */
    public customerRecordPrefix: string;
    public accounts: Array<MeteredAccount>;

    static async load(bucket: string, key: string): Promise<MeteringRegistry> {
        return getDocument<MeteringRegistry>(bucket, key);
    }

    /**
     * The prefix the per customer onboarding records live under. When the
     * registry does not spell it out we look beside the account list itself.
     */
    static customerPrefix(registry: MeteringRegistry, registryKey: string): string {
        if (registry?.customerRecordPrefix) {
            return registry.customerRecordPrefix;
        }
        const directory = (registryKey ?? '').split('/').slice(0, -1).join('/');
        return directory ? `${directory}/customers/` : 'customers/';
    }

    /**
     * Loads the onboarding records that identify the business' billable
     * customers from the same bucket the account list came out of.
     */
    static async loadOnboardedCustomers(
        registry: MeteringRegistry,
        bucket: string,
        registryKey: string,
    ): Promise<OnboardedCustomers> {
        return OnboardedCustomers.load(bucket, MeteringRegistry.customerPrefix(registry, registryKey));
    }
}
