            Ec2InstanceDataGathererService.logger.warn(
                `Leaving ${unplaceable.length} unplaceable instances off the bill: ${unplaceable.sort().join(', ')}`,
            );
        }

        return Object.keys(runningTime)
            .sort()
            .map(
                (customerId) =>
                    new StandardMeasurementEntity({
                        businessID,
                        dimensionId,
                        metadata: {
                            instanceIds: instanceIds[customerId].sort().join(','),
                            instanceCount: instanceIds[customerId].length,
                        },
                        recordValue: Ec2InstanceDataGathererService.roundRunningTime(runningTime[customerId]),
                        customerId,
                        _measurement: UsageEntity._measurement,
                    }),
            );
    }

    /**
     * Splitting an increment between tenants leaves binary floating point dust
     * behind, which finance cannot reconcile. Trim it.
     */
    private static roundRunningTime(runningTime: number): number {
        return Math.round(runningTime * 1e10) / 1e10;
    }

