describe('Ec2InstanceDataGathererService.gatherUsage', () => {
    beforeEach(() => {
        customerRecords = [
            {
                customerId: 'cus_harbor',
                accounts: [{ accountId: '100000000011', dedicated: true }, { accountId: '100000000022' }],
            },
            { customerId: 'cus_lattice', accounts: [{ accountId: '100000000022' }] },
        ];
        instancesByRegion = { 'us-east-1': [], 'us-west-2': [] };
    });

    it('gives every instance in a dedicated account to its customer, tagged or not', async () => {
        instancesByRegion['us-east-1'] = [
            instance('i-001', { meteringDimensionId: 'dim-uptime', meteringCustomerId: 'cus_harbor' }),
            instance('i-002', { meteringDimensionId: 'dim-uptime' }),
            instance('i-003', { meteringDimensionId: 'dim-uptime', meteringCustomerId: 'cus_lattice' }),
        ];

        const measurements = await gather();

        expect(measurements).toHaveLength(1);
        expect(measurements[0].customerId).toEqual('cus_harbor');
        expect(measurements[0].recordValue).toBeCloseTo(increment * 3, 8);
        expect(measurements[0].metadata.instanceIds).toEqual('i-001,i-002,i-003');
        expect(measurements[0].metadata.instanceCount).toEqual(3);
    });

    it('splits a shared instance evenly between the onboarded tenants it names', async () => {
        instancesByRegion['us-west-2'] = [
            instance('i-011', { meteringDimensionId: 'dim-uptime', meteringCustomerId: 'cus_harbor,cus_lattice' }),
        ];

        const measurements = await gather();

        expect(measurements.map(({ customerId }) => customerId)).toEqual(['cus_harbor', 'cus_lattice']);
        measurements.forEach(({ recordValue }) => expect(recordValue).toBeCloseTo(increment / 2, 8));
    });

    it('ignores tagged customers who are not onboarded for the shared account', async () => {
        instancesByRegion['us-west-2'] = [
            instance('i-011', { meteringDimensionId: 'dim-uptime', meteringCustomerId: 'cus_lattice,cus_ghost' }),
        ];

        const measurements = await gather();

        expect(measurements).toHaveLength(1);
        expect(measurements[0].customerId).toEqual('cus_lattice');
        expect(measurements[0].recordValue).toBeCloseTo(increment, 8);
    });

    it('leaves unplaceable shared account usage off the bill', async () => {
        instancesByRegion['us-west-2'] = [
            instance('i-011', { meteringDimensionId: 'dim-uptime' }),
            instance('i-012', { meteringDimensionId: 'dim-uptime', meteringCustomerId: '' }),
            instance('i-013', { meteringDimensionId: 'dim-uptime', meteringCustomerId: 'cus_ghost' }),
        ];

        await expect(gather()).resolves.toEqual([]);
    });

    it('treats an account two customers both claim as dedicated as shared', async () => {
        customerRecords = [
            { customerId: 'cus_harbor', accounts: [{ accountId: '100000000011', dedicated: true }] },
            { customerId: 'cus_lattice', accounts: [{ accountId: '100000000011', dedicated: true }] },
        ];
        instancesByRegion['us-east-1'] = [
            instance('i-001', { meteringDimensionId: 'dim-uptime', meteringCustomerId: 'cus_harbor' }),
            instance('i-002', { meteringDimensionId: 'dim-uptime' }),
        ];

        const measurements = await gather();

        expect(measurements).toHaveLength(1);
        expect(measurements[0].customerId).toEqual('cus_harbor');
        expect(measurements[0].recordValue).toBeCloseTo(increment, 8);
    });

    it('only bills instances tagged with the dimension being metered', async () => {
        instancesByRegion['us-west-2'] = [
            instance('i-011', { meteringDimensionId: 'dim-egress', meteringCustomerId: 'cus_lattice' }),
            instance('i-012', {
                meteringDimensionId: 'dim-uptime,dim-egress',
                meteringCustomerId: 'cus_lattice',
            }),
        ];

        const measurements = await gather();

        expect(measurements).toHaveLength(1);
        expect(measurements[0].metadata.instanceIds).toEqual('i-012');
    });
});
